/* v4 review only · Today's agent setup wizards (AgentSetupModalBase), redrawn faithfully so a review page can show
 * them next to the redesign. Registers only in v4 or when window.ASHA_REVIEW is set.
 * Source of truth (apps/web/src): routes/practice/dentalonboardingform/components/AgentSetupModalBase.tsx (shell,
 * onboarding.wizard* tokens in designsystem/chartDesignSystem.ts), HygieneRecallSetupModal.tsx +
 * components/Specific/HygieneRecallSetup/*, ScheduleOptimizerSetupModal.tsx + components/Specific/ScheduleOptimizerSetup/*,
 * components/Specific/AgentSetup/*, AgentIdentityStep.tsx. Classes are copied from those files (shadcn + asha-ui as it
 * ships today), not from this library's recipes: this is the "before" picture. Patient data is invented. */
(() => {
  if (!(V4 || window.ASHA_REVIEW)) return;

  /* Agent photos: 144px copies of assets/images/agentimages/{stephanie,leena}.png */
  const PHOTO = {
    s: "data:image/jpeg;base64,",
    l: "data:image/jpeg;base64,"
  };

  /* shadcn theme tokens from apps/web/src/index.scss (light): --primary, --secondary, --input, --muted-foreground */
  const PRIMARY = "#0077FF", SECONDARY = "#F8FAFC", INPUT = "#F3F5F7", MUTED = "#6D757E";

  /* ---------------------------------------------------------------- primitives, as the app draws them today */
  const tip = (t) => `data-tip="${esc(t)}"`;
  /* FieldLabel: label + info icon with a tooltip */
  const fieldLabel = (text, tooltip) => `<div class="mb-1.5 flex items-center gap-1.5">${text ? `<label class="inline-flex items-center gap-1.5 text-sm font-medium text-gray-800">${text}</label>` : ""}<button type="button" class="inline-flex cursor-help rounded text-gray-400 transition-colors hover:text-blue-600 focus:outline-none" ${tip(tooltip)} aria-label="More info">${I("info", "size-3.5")}</button></div>`;
  /* SettingInfoTooltip / SettingToggleRow info icon (text-muted-foreground) */
  const mutedInfo = (tooltip) => `<button type="button" class="inline-flex cursor-help rounded transition-colors" style="color:${MUTED}" ${tip(tooltip)} aria-label="Help">${I("info", "size-3.5")}</button>`;
  const qLabel = (text) => `<label class="block text-sm font-medium text-gray-900">${text}</label>`;
  const helpText = (text) => `<p class="text-xs text-gray-500">${text}</p>`;
  /* AshaSwitch (shadcn Switch h-6 w-11, checked bg-blue-600, unchecked bg-input) */
  const sw = (on, label) => `<button type="button" role="switch" aria-checked="${on}" aria-label="${esc(label)}" class="inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors ${on ? "bg-blue-600" : ""}" ${on ? "" : `style="background:${INPUT}"`}><span class="pointer-events-none block size-5 rounded-full bg-white shadow-lg ring-0 transition-transform ${on ? "translate-x-5" : "translate-x-0"}"></span></button>`;
  /* AgentSetupSearchableSelect / AshaCombobox trigger (AshaButton secondary, h-10) */
  const combo = (value, placeholder = "Select...") => `<button type="button" role="combobox" aria-expanded="false" class="inline-flex h-10 w-full items-center justify-between gap-2 whitespace-nowrap rounded-lg border border-gray-200 bg-white px-4 text-sm font-normal text-gray-800 shadow-2xs transition-colors hover:bg-gray-50"><span class="flex min-w-0 items-center gap-1.5"><span class="min-w-0 truncate text-left ${value ? "" : "text-gray-400"}">${esc(value || placeholder)}</span></span>${I("chevron-down", "ml-2 size-3.5 shrink-0 opacity-50")}</button>`;
  /* AshaMultiSelect trigger (shadcn MultiSelect): muted placeholder or "All …" label, chevron right */
  const multi = (text) => `<button type="button" class="flex min-h-9 h-9 w-full cursor-pointer items-center justify-between rounded-lg border border-gray-200 bg-white p-1 shadow-xs transition-colors hover:border-gray-300 hover:bg-gray-50/50" style="color:${MUTED}"><span class="mx-3 truncate text-sm">${esc(text)}</span>${I("chevron-down", "mx-2 h-4 w-4 shrink-0")}</button>`;
  /* AshaTextInput (shadcn Input + asha classes) */
  const input = (value, { cls = "h-10", placeholder = "", pr = "" } = {}) => `<input class="flex ${cls} w-full min-w-0 rounded-lg border border-gray-200 bg-white px-3 py-1 text-sm text-gray-800 shadow-xs outline-none placeholder:text-gray-400 focus-visible:ring-[3px] focus-visible:ring-blue-500/50 ${pr}" value="${esc(value)}" placeholder="${esc(placeholder)}" />`;
  const numberWithSuffix = (value, suffix, wrap = "w-full max-w-36", h = "h-10", pr = "pr-14") => `<div class="relative ${wrap}">${input(value, { cls: h, pr })}<span class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-sm text-gray-500">${suffix}</span></div>`;
  /* Plain number box used on Leena's slot steps: <input class="h-10 w-full rounded-lg border …"> + suffix word */
  const plainNumber = (label, value, suffix) => `<div class="space-y-2"><label class="block text-xs text-gray-500">${label}</label><div class="flex items-center gap-2"><input type="number" value="${value}" class="h-10 w-full rounded-lg border border-gray-200 bg-white px-3 text-sm text-gray-800 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500" /><span class="whitespace-nowrap text-sm text-gray-500">${suffix}</span></div></div>`;
  /* shadcn Slider (Radix): h-2 track bg-secondary, range bg-primary, 20px thumb border-2 border-primary bg-background.
   * Radix keeps the thumb inside the track: offset = 10px at 0%, 0 at 50%, -10px at 100%. */
  const slider = (min, max, values, cls = "py-2") => {
    const vs = Array.isArray(values) ? values : [values];
    const pct = (v) => ((v - min) / (max - min)) * 100;
    const a = vs.length > 1 ? pct(vs[0]) : 0, b = pct(vs[vs.length - 1]);
    const thumb = (p) => `<span class="absolute top-1/2 block size-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-white" style="left:calc(${p.toFixed(2)}% + ${(10 - (p / 50) * 10).toFixed(2)}px);border-color:${PRIMARY}"></span>`;
    return `<div class="relative flex w-full touch-none select-none items-center ${cls}" role="slider" aria-valuemin="${min}" aria-valuemax="${max}" aria-valuenow="${vs[0]}"><div class="relative h-2 w-full grow overflow-hidden rounded-full" style="background:${SECONDARY}"><div class="absolute h-full" style="left:${a}%;width:${b - a}%;background:${PRIMARY}"></div></div>${vs.map((v) => thumb(pct(v))).join("")}</div>`;
  };
  const blueValue = (t) => `<span class="text-sm font-semibold text-blue-600">${t}</span>`;

  /* StepExplanation (title text-xl, description text-sm) */
  const explain = (title, desc, cls = "mb-6") => `<div class="${cls} space-y-4"><div class="max-w-2xl space-y-2"><h3 class="text-xl font-semibold tracking-tight text-gray-900">${esc(title)}</h3><p class="text-sm leading-relaxed text-gray-500">${esc(desc)}</p></div></div>`;
  const stepWrap = (inner) => `<div class="w-full max-w-2xl space-y-6">${inner}</div>`;
  /* AgentSetupWizardSubsection (+ AshaSectionHeader sm) */
  const subsection = ({ title = "", desc = "", actions = "", body = "", divider = false }) => `<section class="space-y-4 ${divider ? "border-t border-gray-100 pt-6" : ""}">
    ${title || desc || actions ? `<div class="flex items-start justify-between gap-4">${title ? `<div class="space-y-1"><h3 class="text-sm font-semibold text-gray-900">${esc(title)}</h3>${desc ? `<p class="text-xs text-gray-500">${esc(desc)}</p>` : ""}</div>` : ""}${actions ? `<div class="flex shrink-0 items-center gap-2">${actions}</div>` : ""}</div>` : ""}
    ${body ? `<div class="space-y-4">${body}</div>` : ""}</section>`;
  /* AshaFormSection density="compact" */
  const formSection = ({ title, desc = "", actions = "", body, divider = false }) => `<section class="space-y-3 ${divider ? "border-t border-gray-100 pt-4" : ""}"><div class="flex items-start justify-between gap-4"><div class="min-w-0"><h3 class="text-sm font-semibold text-gray-900">${title}</h3>${desc ? `<p class="mt-0.5 text-xs text-gray-500">${desc}</p>` : ""}</div>${actions ? `<div class="flex shrink-0 items-center gap-2">${actions}</div>` : ""}</div><div class="space-y-3">${body}</div></section>`;
  /* SettingToggleRow (AshaSwitchRow with the card stripped: py-3 only) */
  const toggleRow = (label, tooltip, desc, on) => `<div class="flex items-start justify-between gap-4 py-3"><div class="flex min-w-0 gap-3"><div class="min-w-0 text-sm text-gray-800"><div class="space-y-1"><div class="flex items-center gap-1.5"><span class="cursor-pointer text-sm font-semibold text-gray-900">${esc(label)}</span>${mutedInfo(tooltip)}</div><p class="text-xs leading-relaxed text-gray-500">${esc(desc)}</p></div></div></div><span class="mt-1 shrink-0">${sw(on, label)}</span></div>`;
  /* SkippedPayersConfig layout="flat", nothing skipped yet */
  const payerSkip = ({ emptyTitle = "No insurance plans are being skipped", emptyAction = "Use the search above to add insurance plans to skip." } = {}) => `<div class="space-y-4">
    <div class="space-y-2"><label class="text-sm font-medium text-gray-900">Find an insurance plan</label><p class="text-xs text-gray-500">Patients with these insurance plans will be excluded from automated outreach.</p>
      <div class="relative">${I("search", "pointer-events-none absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-gray-400")}${input("", { cls: "h-9", placeholder: "Type an insurance plan name...", pr: "pl-10" })}</div></div>
    <div class="flex flex-col items-center justify-center py-6 text-center"><span class="inline-flex size-10 items-center justify-center rounded-lg border border-gray-100 bg-white text-gray-400">${I("shield-off", "size-5")}</span><h3 class="mt-3 text-sm font-semibold text-gray-900">${esc(emptyTitle)}</h3><p class="mt-1 max-w-sm text-sm text-gray-500">${esc(emptyAction)}</p></div></div>`;

  /* ---------------------------------------------------------------- shared steps */
  const introStep = (a) => `<div class="flex min-h-full flex-1 flex-col items-center justify-center"><div class="flex w-full max-w-4xl flex-col items-center px-6">
      <div class="relative mb-4"><div class="size-24 overflow-hidden rounded-full border-4 border-white shadow-xl"><img src="${PHOTO[a.key]}" alt="${esc(a.photoAlt)}" class="h-full w-full object-cover" /></div>
        <div class="absolute -bottom-2 -right-2 rounded-full bg-blue-600 p-2 text-white shadow-lg">${I("sparkles", "size-4")}</div></div>
      <div class="mb-6 w-full space-y-2 text-center"><h2 class="text-2xl font-semibold tracking-tight text-gray-900">${esc(a.introTitle)}</h2><p class="mx-auto max-w-2xl text-base leading-relaxed text-gray-500">${esc(a.introBody)}</p></div>
      <button type="button" data-today-go="next" class="inline-flex h-12 items-center justify-center gap-2 rounded-lg bg-blue-600 px-6 text-sm font-medium text-white hover:bg-blue-700">Start Setup${I("chevron-right", "size-5")}</button></div></div>`;
  const videoBox = `<div class="relative aspect-video w-full overflow-hidden rounded-xl border border-gray-200 bg-gray-900"><div class="absolute inset-0 flex items-center justify-center"><span class="flex size-16 items-center justify-center rounded-full bg-white/90 text-gray-900 shadow-lg">${I("play", "ml-1 size-7 fill-current")}</span></div><p class="absolute bottom-3 left-4 text-xs font-medium text-white/70">Embedded intro video</p></div>`;
  const identityFields = (name) => `<div class="grid w-full gap-6">
      <div class="space-y-1">${fieldLabel("Agent Name", "The name the agent will use to introduce themselves to patients.")}${input(name, { cls: "h-10", placeholder: "e.g. Sarah" })}</div>
      <div class="space-y-1">${fieldLabel("Voice", "Choose a voice that matches your practice's brand personality.")}<button type="button" role="combobox" class="inline-flex h-10 w-full items-center justify-between rounded-lg border border-gray-200 bg-white px-3 text-sm font-normal shadow-xs"><span class="min-w-0 flex-1 truncate text-left"><span class="font-medium text-gray-900">Jessica</span><span class="text-gray-500"> · Warm and upbeat, American English</span></span><span class="ml-2 shrink-0 rounded-md border border-blue-200 bg-blue-50 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-blue-700">ARIA Voice</span>${I("chevron-down", "ml-2 h-4 w-4 shrink-0 opacity-50")}</button></div>
      <div class="space-y-1">${fieldLabel("Voice Model", "Choose which voice model powers this agent. Leave on system default unless you have a reason to override.")}<button type="button" class="inline-flex h-10 w-full items-center justify-between rounded-lg border border-gray-200 bg-white px-3 text-sm font-normal shadow-xs"><span class="min-w-0 flex-1 truncate text-left"><span class="font-medium text-gray-900">Standard</span></span><span class="ml-2 shrink-0 rounded-md border border-blue-200 bg-blue-50 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-blue-700">Default</span>${I("chevron-down", "ml-2 h-4 w-4 shrink-0 opacity-50")}</button></div></div>`;
  const customContextStep = (name) => `<div class="w-full max-w-2xl space-y-6">${explain("Custom Context", "Add practice-specific instructions for how this agent should communicate and handle edge cases. These apply across outreach and are the same settings you'll find later under Configure Agent.", "mb-4")}
    <div class="space-y-6"><div class="space-y-4">
      <div class="flex items-center gap-2 rounded-lg border border-gray-200 bg-gray-50/60 px-3 py-2.5 text-xs"><div class="flex min-w-0 flex-1 items-center gap-2"><span aria-hidden="true" class="size-1.5 shrink-0 rounded-full bg-gray-300"></span><span class="font-medium" style="color:${MUTED}">No custom instructions are active for ${esc(name)} yet.</span></div>
        <button type="button" disabled class="inline-flex h-8 shrink-0 items-center rounded-md px-2.5 text-xs font-medium text-gray-600 opacity-50">${I("sparkles", "mr-1.5 size-3.5 shrink-0")}Format with AI</button></div>
      <textarea class="min-h-[260px] w-full resize-none rounded-lg border border-gray-200 bg-gray-50/40 px-3 py-2 text-sm leading-relaxed text-gray-800 placeholder:text-gray-500 focus-visible:bg-white" placeholder="${esc('Examples:\n• "Always greet patients by their first name."\n• "Keep text messages brief and friendly."\n• "On phone calls, speak slowly and clearly."\n• "We have a teeth whitening promotion this month."')}" aria-label="Custom context"></textarea>
      <div class="flex flex-wrap items-center justify-between gap-3 pt-1"><span class="text-xs text-gray-500">Apply changes to validate and make this live.</span><button type="button" disabled class="inline-flex h-8 items-center rounded-md bg-blue-600 px-3 text-xs font-medium text-white opacity-50">Apply changes</button></div></div></div></div>`;
  const ACTIVATION = [
    ["activate", "Turn on now", "Start this agent using the settings you just configured. You can change or turn it off any time."],
    ["saveForLater", "Save for later", "Keep these settings but do not start the agent yet. Nothing runs until you turn it on."]
  ];
  /* AgentSetupConfirmStep + WizardActivationChoiceCards (compact) */
  const confirmStep = (a, choice) => `<div class="w-full max-w-2xl space-y-6">${explain("Review & Confirm", "You're using the same settings available in Agent Settings. You can change anything later from the agent dashboard.")}
    <div class="space-y-3"><p class="text-sm font-medium text-gray-900">Ready to turn on this agent?</p>
      <div class="grid w-full max-w-2xl gap-3" style="grid-template-columns:repeat(auto-fit,minmax(min(16rem,100%),1fr))">${ACTIVATION.map(([v, l, d]) => { const on = v === choice;
        return `<button type="button" data-today-choice="${v}" aria-pressed="${on}" aria-label="${esc(a.name)}: ${esc(l)}" class="group/choice relative flex min-h-[72px] cursor-pointer items-start gap-3 rounded-xl border p-3 text-left transition-all ${on ? "border-blue-500 bg-blue-50/40 ring-1 ring-blue-500/30" : "border-gray-200 bg-white hover:border-gray-300 hover:bg-gray-50/50"}">
          <span class="mt-0.5 inline-flex size-6 shrink-0 items-center justify-center rounded-full border transition-colors ${on ? "border-blue-500 bg-blue-600 text-white" : "border-gray-300 text-transparent"}">${I("circle-check", "size-3")}</span>
          <span class="min-w-0"><span class="block text-sm font-semibold text-gray-900">${l}</span><span class="mt-1 block text-sm leading-6 text-gray-500">${d}</span></span></button>`; }).join("")}</div></div></div>`;

  /* ---------------------------------------------------------------- Stephanie (hygiene recall) steps */
  const HY = {
    recallLabel: (l) => `Which recall list should Stephanie use for ${l.toLowerCase()}?`,
    recallHelp: "Pick the recall list in your practice that tracks these patients. This works whether you use Asha PMS or an external system.",
    apptLabel: "What appointment should Stephanie offer when patients book?",
    apptHelp: (ex) => `Choose the appointment type from your schedule that matches this recall. Example: ${ex}`,
    leadLabel: "How early should Stephanie start reaching out?",
    leadHelp: "Stephanie begins contacting patients this many days before their recall due date.",
    provLabel: "Whose name should Stephanie use in messages?",
    provHelp: 'Optional. Adds a personal touch—for example, "Dr. Smith recommends scheduling your cleaning."'
  };
  /* RecallDueDateOffsetField inside SettingField/AshaField */
  const offsetField = `<div class="space-y-2"><div><label class="inline-flex items-center gap-1 text-sm font-medium text-gray-900"><span class="inline-flex items-center gap-1.5"><span>How many days after the recall interval should Asha compute recall dates?</span>${mutedInfo("When Asha calculates when each patient is due, it starts from their last visit plus the recall interval, then adds this many days.")}</span></label></div>
    <div>${numberWithSuffix("1", "days", "w-32", "h-9", "pr-16")}<p class="mt-1 text-xs text-gray-500">This applies everywhere in Asha for this recall list. Most practices use 1 day.</p></div></div>`;
  const recallFields = ({ label, list, appt, example, withAge }) => `
    <div class="space-y-2">${qLabel(HY.recallLabel(label))}${combo(list, "Search recall lists...")}${helpText(HY.recallHelp)}</div>
    ${offsetField}
    <div class="space-y-2">${qLabel(HY.apptLabel)}${combo(appt, "Select appointment type...")}${helpText(esc(HY.apptHelp(example)))}</div>
    <div class="space-y-2">${qLabel(HY.leadLabel)}${numberWithSuffix("30", "days")}${helpText(HY.leadHelp)}</div>
    <div class="space-y-2">${qLabel(HY.provLabel)}${combo("No provider name")}${helpText(esc(HY.provHelp))}</div>
    ${withAge ? toggleRow("Should younger patients get a different appointment type?", "When enabled, patients under the age cutoff are booked with a child appointment instead of the adult one.", "Turn this on if your practice books child cleanings separately.", false) : ""}`;
  const stephanieStep = (id, a) => {
    switch (id) {
      case "about": return stepWrap(`${explain("About Stephanie", "Learn how Stephanie can help your practice.")}${videoBox}`);
      case "identity": return stepWrap(`${explain("Agent Identity", "Choose Stephanie's name, voice, and how they sound on calls.")}${identityFields("Stephanie")}`);
      case "adult-prophy": return stepWrap(`${explain("Adult cleanings", "Choose your adult cleaning recall list, which appointment Stephanie should book, and when to start reaching out.")}
        ${subsection({ title: "Should the hygiene recall agent reach out for adult cleanings or try to book additional cleanings?", desc: "Routine 6-month cleanings.", actions: sw(true, "Adult cleanings"),
          body: recallFields({ label: "Adult cleanings", list: "Prophy - 6 Month (1,284)", appt: "6-Month Adult Recall", example: '"6-Month Adult Recall" or "Adult Prophylaxis"', withAge: true }) })}`);
      case "perio-maintenance": return stepWrap(`${explain("Perio maintenance", "Choose your perio maintenance recall list, which appointment Stephanie should book, and when to start reaching out.")}
        ${subsection({ title: "Should the hygiene recall agent reach out for deep cleanings or try to book additional deep cleanings?", desc: "Perio maintenance visits, usually every 3–4 months.", actions: sw(true, "Perio maintenance"),
          body: recallFields({ label: "Perio maintenance", list: "Perio Maint - 3 Month (212)", appt: "Perio Maintenance", example: '"Perio Maintenance"', withAge: false }) })}`);
      case "procedure-codes": return stepWrap(`${explain("Hygiene visit procedure codes", "Tell Asha which procedure codes count as hygiene visits when checking patient history.")}
        <div class="space-y-4"><button type="button" class="flex h-auto min-h-10 w-full items-center justify-between rounded-md border border-gray-200 bg-white p-1 text-sm shadow-xs"><div class="flex min-w-0 flex-1 flex-wrap items-center">${["D1110 - Adult Prophy", "D1120 - Child Prophy", "D4910 - Perio Maintenance"].map((c) => `<span class="m-1 inline-flex h-[26px] items-center rounded-md border border-gray-200 px-2 text-xs font-medium"><span class="max-w-[200px] truncate text-gray-800">${c}</span><span class="ml-1 inline-flex text-gray-400">${I("circle-x", "size-4")}</span></span>`).join("")}</div>${I("chevron-down", "mx-2 h-4 w-4 shrink-0 text-gray-400")}</button>
          ${helpText("Asha pre-selects common hygiene codes from your catalog when they exist (for example D1110, D1120, D4910). Remove any that don't apply.")}</div>`);
      case "criteria": return stepWrap(`${explain("Scheduling & Daily Limits", "Set how many patients Stephanie contacts and how far ahead she can schedule.")}
        <div class="space-y-0">
          ${formSection({ title: fieldLabel("How many patients should Stephanie contact each day?", "This caps how many patients Stephanie contacts in a single day so your team can keep up."), actions: blueValue("20 patients"),
            body: `${slider(5, 100, 20)}<div class="flex justify-between text-xs text-gray-500"><span>5 patients</span><span>100 patients</span></div>` })}
          ${formSection({ divider: true, title: fieldLabel("Should Stephanie also contact patients whose recall is coming up soon?", "In addition to overdue recalls, Stephanie can also reach out to patients whose recall is coming due within this window."), desc: "Set to 0 if you only want overdue patients contacted.", actions: blueValue("30 days"),
            body: `${slider(0, 90, 30)}<div class="flex justify-between text-xs text-gray-500"><span>Overdue only</span><span>90 days ahead</span></div>` })}
          ${formSection({ divider: true, title: fieldLabel("What's the soonest appointment Stephanie can offer?", "Only show appointment slots at least this many days from today."), actions: blueValue("3 days out"),
            body: `${slider(0, 30, 3)}<div class="flex justify-between text-xs text-gray-500"><span>Same day</span><span>30 days out</span></div>` })}
          ${formSection({ divider: true, title: "Same-hygienist preference",
            body: toggleRow("Should Stephanie try to book with the same hygienist the patient saw last time?", "When enabled, Stephanie only offers slots with the provider from the patient's most recent hygiene visit when that can be determined.", "Helps keep recall visits with the same hygienist.", false) })}
        </div>`);
      case "insurance-exclusions": return stepWrap(`${explain("Insurance Exclusions", "Choose insurance plans Stephanie should skip when contacting patients for recall.")}
        <div class="space-y-6"><p class="text-sm text-gray-600">During an active outreach, Stephanie follows Asha's standard cadence: SMS, a 24-hour follow-up SMS, a voice call, then weekly SMS and call cycles before a longer pause. That timing is not configurable here.</p>
          ${payerSkip({ emptyAction: "Search above to add plans Stephanie should skip." })}</div>`);
      case "custom-context": return customContextStep("Stephanie");
      default: return "";
    }
  };

  /* ---------------------------------------------------------------- Leena (schedule optimizer) steps */
  const entityFilters = (dividerFirst = false) => `
    ${subsection({ divider: dividerFirst, title: "Which providers should this apply to?", desc: "All providers are included by default. Choose specific providers to narrow the scope; clearing the selection includes everyone.", body: multi("All providers") })}
    ${subsection({ divider: true, title: "Which appointment types should this apply to?", desc: "Leave empty to include every appointment type in your practice.", body: multi("All appointment types") })}`;
  const taskCard = (label, tooltip, desc, on) => `<div class="flex items-center justify-between rounded-xl border border-gray-200 bg-white p-4 transition-colors hover:border-gray-300"><div class="space-y-0.5"><div class="flex items-center gap-2"><label class="text-sm font-medium text-gray-900">${label}</label>${fieldLabel("", tooltip)}</div><p class="text-xs text-gray-500">${desc}</p></div>${sw(on, label)}</div>`;
  const sliderField = (label, tooltip, value, min, max, v) => `<div class="space-y-3"><div class="flex justify-between">${fieldLabel(label, tooltip)}${blueValue(value)}</div>${slider(min, max, v)}</div>`;
  const leenaStep = (id) => {
    switch (id) {
      case "about": return `<div class="w-full max-w-2xl space-y-6"><div class="w-full space-y-6"><div class="space-y-2 text-center"><h3 class="text-xl font-semibold tracking-tight text-gray-900">About Leena</h3><p class="text-sm text-gray-500">Learn how Leena can help your practice.</p></div>${videoBox}</div></div>`;
      case "identity": return `<div class="w-full space-y-6"><div class="max-w-2xl space-y-2"><h3 class="text-xl font-semibold tracking-tight text-gray-900">Agent Identity</h3><p class="text-sm leading-relaxed text-gray-500">Customize how your agent introduces themselves.</p></div>${identityFields("Leena")}</div>`;
      case "features": return stepWrap(`${explain("Which schedule tasks should Leena run?", "Turn on the outreach tasks you want Leena to run. You can fine-tune providers, timing, and insurance exclusions in the next steps.")}
        <div class="grid gap-4">${taskCard("Confirm Upcoming Appointments", "Send confirmation requests before appointments and follow up if patients don't respond.", "Call and text patients before visits so they confirm or free up the slot.", true)}
          ${taskCard("Fill Cancellations", "When someone cancels, automatically find patients who could fill that slot.", "When someone cancels, find patients who can fill the opening sooner.", true)}</div>`);
      case "confirmation": return stepWrap(`${explain("When should Leena confirm upcoming appointments?", "Choose how far ahead Leena reaches out, which appointments qualify, and any insurance plans to skip.")}
        <div class="space-y-6"><div class="space-y-3"><div class="flex justify-between">${fieldLabel("Send Confirmation Requests", "How far in advance should Leena send confirmation requests?")}${blueValue("7 days before")}</div>${slider(1, 14, 7)}<div class="flex justify-between text-xs font-medium uppercase tracking-wide text-gray-400"><span>1 Day</span><span>14 Days</span></div></div>
          ${entityFilters(false)}
          ${subsection({ divider: true, title: "Are there insurance plans Leena should skip for confirmations?", desc: "Patients with these payers will not receive appointment confirmation outreach.", body: payerSkip() })}</div>`);
      case "slotfilling": return stepWrap(`${explain("When should Leena try to fill open schedule slots?", "Set which open slots and scheduled patients Leena should target when trying to fill cancellations.")}
        <div class="space-y-6">
          ${subsection({ title: "Which open slots should Leena try to fill?", body: `<div class="grid gap-4 sm:grid-cols-2">${plainNumber("Start looking", 0, "days from today")}${plainNumber("Stop looking", 7, "days from today")}</div>` })}
          ${subsection({ divider: true, title: "Which scheduled patients should Leena contact?", body: `<div class="flex items-center gap-4"><div class="flex-1">${plainNumber("From", 7, "days out")}</div><div class="flex-1">${plainNumber("To", 30, "days out")}</div></div>` })}
          ${entityFilters(false)}
          ${subsection({ divider: true, title: "How many patients should Leena contact per open slot?", body: `<div class="space-y-4">${sliderField("Patients at once", "How many patients Leena contacts at the same time for one opening.", "3", 1, 10, 3)}${sliderField("Total patients per opening", "Total patients to offer the slot before Leena stops outreach for that opening.", "10", 1, 50, 10)}</div>` })}
          ${subsection({ divider: true, title: "Which visit lengths can be moved?", body: `${fieldLabel("Allowed visit durations", "Set the range of appointment durations eligible for slot filling. Only appointments within this range will be contacted.")}
            <p class="text-xs text-gray-500">Set the range of appointment lengths that can be moved to fill open slots.</p>
            <div class="space-y-2"><div class="flex items-center justify-between"><label class="text-xs text-gray-500">Duration Range</label>${blueValue("30 – 90 min")}</div>
              <div class="space-y-3 pt-2">${slider(15, 120, [30, 90], "")}<div class="flex items-center justify-between text-xs text-gray-400"><span>15 min</span><span>120 min</span></div></div></div>` })}
          ${subsection({ divider: true, title: "Are there insurance plans Leena should skip for slot filling?", desc: "Patients with these payers will not receive move-up outreach.", body: payerSkip() })}
        </div>`);
      case "custom-context": return customContextStep("Leena");
      default: return "";
    }
  };

  /* ---------------------------------------------------------------- the two agents */
  const AGENTS_TODAY = {
    s: { key: "s", name: "Stephanie", role: "Hygiene Recall Coordinator", photoAlt: "Stephanie, AI Hygiene Recall",
      introTitle: "Meet Stephanie, Your Hygiene Recall Coordinator",
      introBody: "Stephanie identifies patients who are due or overdue for hygiene recall, reaches out by text or phone, and books their next cleaning or perio maintenance visit.",
      steps: [["intro", "Meet Stephanie", "sparkles"], ["about", "About Stephanie", "circle-play"], ["identity", "Agent Identity", "mic"], ["adult-prophy", "Adult Cleanings", "user-round"], ["perio-maintenance", "Perio Maintenance", "activity"], ["procedure-codes", "Procedure Codes", "file-code"], ["criteria", "Scheduling", "sliders-horizontal"], ["insurance-exclusions", "Insurance Exclusions", "shield-ban"], ["custom-context", "Custom Context", "book-open"], ["confirm", "Review & Confirm", "clipboard-check"]],
      content: stephanieStep },
    l: { key: "l", name: "Leena", role: "Schedule Optimizer", photoAlt: "Leena, AI Schedule Optimizer",
      introTitle: "Meet Leena, Your Schedule Optimizer",
      introBody: "Asha's AI optimizes your schedule by calling and texting patients to confirm appointments and fill any open slots. It uses intelligent patient memory and performs dozens of actions to take your schedule from patchy to filled.",
      steps: [["intro", "Meet Leena", "sparkles"], ["about", "About Leena", "circle-play"], ["identity", "Agent Identity", "mic"], ["features", "Tasks", "trending-up"], ["confirmation", "Confirmations", "calendar"], ["slotfilling", "Filling Cancellations", "clock"], ["custom-context", "Custom Context", "book-open"], ["confirm", "Review & Confirm", "clipboard-check"]],
      content: leenaStep }
  };

  /* ---------------------------------------------------------------- the dialog (AgentSetupModalBase, desktop layout) */
  const NAV = {
    base: "group flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-colors text-left",
    active: "bg-white text-blue-700 ring-1 ring-gray-200 shadow-[0_1px_0_rgba(0,0,0,0.03)]",
    done: "text-gray-700 hover:bg-gray-100 cursor-pointer",
    open: "text-gray-500 hover:bg-gray-100 cursor-pointer",
    off: "text-gray-400 cursor-not-allowed"
  };
  const SCROLL = "[&::-webkit-scrollbar]:w-2 [&::-webkit-scrollbar-thumb]:rounded-none [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:bg-gray-200";
  const dialog = (a, step, choice) => {
    const n = a.steps.length, pct = Math.round(((step + 1) / n) * 100), last = step === n - 1, id = a.steps[step][0];
    const nav = a.steps.map(([, title, icon], i) => {
      const active = i === step, done = step > i, can = step > 0 || i === 0;
      return `<button type="button" data-today-go="${i}" ${can ? "" : "disabled"} ${active ? 'aria-current="step"' : ""} class="${NAV.base} ${active ? NAV.active : done ? NAV.done : can ? NAV.open : NAV.off}">${I(icon, `h-4 w-4 shrink-0 transition-colors ${active ? "text-blue-600" : done ? "text-green-600" : "text-gray-400"}`)}<span class="flex-1 truncate">${esc(title)}</span>${done ? I("circle-check", "h-3.5 w-3.5 shrink-0 text-green-600") : ""}</button>`;
    }).join("");
    const body = id === "intro" ? introStep(a) : id === "confirm" ? confirmStep(a, choice) : a.content(id, a);
    const nextLabel = last ? (choice === "activate" ? "Turn on now" : "Save for later") : "Continue";
    return `<div role="dialog" aria-modal="true" aria-label="Set up ${esc(a.name)}" class="absolute left-1/2 top-1/2 z-10 flex -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-2xl border border-gray-200 bg-white p-0 shadow-2xl" style="width:min(1024px,96%);height:780px">
      <div class="flex h-full w-full flex-col"><div class="flex min-h-0 flex-1 overflow-hidden">
        <div class="flex w-72 shrink-0 min-h-0 flex-col border-r border-gray-200 bg-gray-50/80">
          <div class="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto p-6 ${SCROLL}">
            <div class="flex min-w-0 items-center gap-3"><div class="size-11 shrink-0 overflow-hidden rounded-lg border border-gray-200 bg-gray-100"><img src="${PHOTO[a.key]}" alt="${esc(a.name)}" class="h-full w-full object-cover" /></div>
              <div class="min-w-0"><h2 class="truncate text-sm font-semibold leading-tight text-gray-900">${esc(a.name)}</h2><p class="truncate text-[11px] font-semibold uppercase tracking-[0.08em] text-blue-600">${esc(a.role)}</p></div></div>
            <nav class="flex flex-col gap-1" aria-label="Setup steps">${nav}</nav></div>
          <div class="shrink-0 border-t border-gray-200 bg-gray-50/95 px-6 py-4"><div class="h-1.5 w-full overflow-hidden rounded-full bg-gray-200"><div class="h-full rounded-full bg-blue-600" style="width:${pct}%"></div></div><p class="mt-2 text-right text-[11px] font-medium tabular-nums text-gray-500">${pct}% complete</p></div>
        </div>
        <div class="flex min-w-0 flex-1 flex-col bg-white">
          <div data-today-body class="flex min-h-0 flex-1 flex-col overflow-y-auto px-10 py-8 pb-10 ${SCROLL}"><div class="flex min-h-full flex-1 flex-col">${body}</div></div>
          ${step > 0 ? `<div class="flex shrink-0 items-center justify-between gap-2 border-t border-gray-200 bg-white px-10 py-3.5">
            <button type="button" data-today-go="back" class="inline-flex h-9 items-center gap-1 rounded-lg px-3 text-sm font-medium text-gray-600 hover:bg-gray-100 hover:text-gray-900">${I("chevron-left", "h-4 w-4")}Back</button>
            <button type="button" data-today-go="next" class="inline-flex h-9 items-center gap-1.5 rounded-lg bg-blue-600 px-4 text-sm font-medium text-white shadow-sm hover:bg-blue-700">${nextLabel}${last ? "" : I("chevron-right", "h-4 w-4 opacity-80")}</button></div>` : ""}
        </div></div></div>
      <button type="button" class="absolute right-4 top-4 z-20 rounded-sm text-gray-900 opacity-70 transition-opacity hover:opacity-100" aria-label="Close">${I("x", "h-4 w-4")}</button></div>`;
  };

  /* The page the dialog opens over (a sketch of AI Staff) under shadcn's bg-black/80 overlay */
  const backdrop = () => `<div class="absolute inset-0 overflow-hidden" aria-hidden="true" inert data-scroll-ok>
    <div class="flex h-full"><div class="w-56 shrink-0 space-y-2 border-r border-gray-200 bg-white p-4">${Array.from({ length: 9 }, (_, i) => `<div class="h-7 rounded-md ${i === 4 ? "bg-gray-100" : ""}"><span class="mt-2 ms-2 block h-3 rounded bg-gray-200" style="width:${[60, 72, 54, 66, 70, 58, 64, 50, 68][i]}%"></span></div>`).join("")}</div>
      <div class="min-w-0 flex-1 bg-gray-50 p-8"><p class="text-2xl font-semibold text-gray-800">AI Staff</p><p class="mt-1 text-sm text-gray-500">Set up the agents that work for Bayview Family Dental.</p>
        <div class="mt-6 grid grid-cols-3 gap-4">${["Amy · Receptionist", "Stephanie · Hygiene Recall", "Leena · Schedule Optimizer", "Laura · Insurance Caller", "Kim · Case Acceptance", "Helen · Patient Billing"].map((t) => `<div class="rounded-xl border border-gray-200 bg-white p-4"><div class="flex items-center gap-3"><span class="size-10 rounded-full bg-gray-200"></span><div><p class="text-sm font-semibold text-gray-800">${t}</p><p class="text-xs text-gray-500">Not set up</p></div></div><span class="mt-4 block h-8 w-28 rounded-lg bg-blue-600/80"></span></div>`).join("")}</div></div></div>
    <div class="absolute inset-0 bg-black/80"></div></div>`;

  const render = (agentKey, step, choice = "activate") => `<div class="relative h-[840px] overflow-hidden">${backdrop()}${dialog(AGENTS_TODAY[agentKey], step, choice)}</div>`;
  const STATES = {
    "Stephanie · Adult cleanings": ["s", 3],
    "Stephanie · Scheduling": ["s", 6],
    "Stephanie · Review & confirm": ["s", 9],
    "Leena · Filling cancellations": ["l", 5],
    "Leena · Review & confirm": ["l", 7]
  };

  defineBlock({
    cat: "ai", id: "ai-agent-setup-today", title: "Agent setup wizard (today)",
    /* No "where" and a short note: five long state names already fill most of the header row */
    note: "The shipped Stephanie and Leena setup dialog, drawn from today's code. Steps, Back and Continue work.",
    states: Object.keys(STATES),
    canvas: "bare",
    html: (state) => { const [k, s] = STATES[state] || STATES["Stephanie · Adult cleanings"]; return render(k, s); },
    mount(el, state) {
      const [k, s] = STATES[state] || STATES["Stephanie · Adult cleanings"];
      el._today = { agent: k, step: s, choice: "activate" };
      if (el._todayBound) return; el._todayBound = true;
      el.addEventListener("click", (e) => {
        const go = e.target.closest("[data-today-go]"), pick = e.target.closest("[data-today-choice]"), t = el._today;
        if ((!go && !pick) || !el.contains(go || pick) || (go && go.disabled)) return;
        const a = AGENTS_TODAY[t.agent];
        if (pick) t.choice = pick.dataset.todayChoice;
        else { const v = go.dataset.todayGo; if (v === "next" && t.step === a.steps.length - 1) return;
          t.step = v === "next" ? t.step + 1 : v === "back" ? Math.max(0, t.step - 1) : +v; }
        el.innerHTML = render(a.key, t.step, t.choice); icons();
      });
    }
  });
})();
